import type {
  CheckboxGroupProps,
  CheckboxGroupItemProps,
  CheckedStatus,
} from "./checkbox-group.types";

import {
  forwardRef,
  Children,
  isValidElement,
  useState,
  cloneElement,
  ReactElement,
  useCallback,
  useMemo,
} from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Checkbox } from "@components/checkbox";
import { useUniqueId } from "@system";

import { CheckboxGroupClasses, StyledCheckboxGroup } from "./checkbox-group.styles";

const CheckboxGroupRoot = forwardRef<HTMLDivElement, CheckboxGroupProps>(
  (
    {
      className,
      defaultValue = [],
      value,
      onValueChange,
      variant = "default",
      required = false,
      disabled = false,
      orientation = "vertical",
      size = "default",
      children,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const isControlled = value !== undefined;
    const [internalValues, setInternalValues] = useState<string[]>(defaultValue);
    const selectedValues = useMemo(
      () => (isControlled ? (Array.isArray(value) ? value : []) : internalValues),
      [isControlled, value, internalValues],
    );

    const toggleValue = useCallback(
      (val: string) => {
        const nextValues = selectedValues.includes(val)
          ? selectedValues.filter((v) => v !== val)
          : [...selectedValues, val];

        if (!isControlled) {
          setInternalValues(nextValues);
        }

        onValueChange?.(nextValues);
      },
      [selectedValues, isControlled, onValueChange],
    );

    const childrenWithProps = Children.map(children, (child) => {
      if (!isValidElement(child)) return child;
      const { value: childValue, disabled: itemDisabled, variant: childVariant } = child.props;
      const isChecked = selectedValues.includes(childValue);
      const isDisabled = disabled || itemDisabled;

      const handleCheckedChange = (checked: CheckedStatus) => {
        if (checked === true && !isChecked) {
          toggleValue(childValue);
        } else if (checked === false && isChecked) {
          toggleValue(childValue);
        }
      };

      return cloneElement(child as ReactElement<CheckboxGroupItemProps>, {
        checked: isChecked,
        disabled: isDisabled,
        // Respect individual item variant if set, otherwise use group variant
        variant: childVariant || variant,
        onCheckedChange: handleCheckedChange,
      });
    });

    const rootClasses = clsx(CheckboxGroupClasses.root, className, {
      [CheckboxGroupClasses.sm]: size === "sm",
    });

    return (
      <StyledCheckboxGroup
        ref={ref}
        aria-required={required}
        className={rootClasses}
        currentTheme={theme}
        data-orientation={orientation}
        disabled={disabled}
        role="group"
        variant={variant}
        {...props}
        onChange={undefined} // prevent passing down onChange from react-hook-form (onValueChange should be used instead)
      >
        {childrenWithProps}
      </StyledCheckboxGroup>
    );
  },
);
CheckboxGroupRoot.displayName = "CheckboxGroup";

const Item = forwardRef<HTMLInputElement, CheckboxGroupItemProps>(
  (
    { label, subtext, checked = false, onCheckedChange, disabled, value, variant, ...props },
    ref,
  ) => {
    const handleChange = (checked: CheckedStatus) => {
      onCheckedChange?.(checked);
    };
    const generatedId = useUniqueId("checkbox-group-item");
    const id = props.id ?? generatedId;

    return (
      <div ref={ref} className={clsx(CheckboxGroupClasses.item)}>
        <Checkbox
          checked={checked}
          disabled={disabled}
          id={id}
          value={value}
          variant={variant}
          onCheckedChange={handleChange}
          {...props}
        />
        <label className={CheckboxGroupClasses.itemLabel} data-disabled={disabled} htmlFor={id}>
          <span className={CheckboxGroupClasses.itemLabelText}>{label}</span>
          {subtext && <span className={CheckboxGroupClasses.itemSubtext}>{subtext}</span>}
        </label>
      </div>
    );
  },
);
Item.displayName = "CheckboxGroup.Item";

const CheckboxGroup = Object.assign(CheckboxGroupRoot, {
  Item,
});

export default CheckboxGroup;
